  match r, t with
  | 1, (StA, S0) => [SWin 3]
  | 1, (StA, S1) => [SWin 3;SCycR 3;SWinR 2;SCycL 3 0;SWin 10]
  | 1, (StB, S0) => [SWin 3;SCycR 3;SWinR 1]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => []
  | 1, (StC, S1) => [SWin 3;SCycR 3;SWinR 2]
  | 1, (StD, S0) => [SWin 2]
  | 1, (StD, S1) => [SWin 3;SCycR 3;SWinR 2;SCycL 3 0;SWin 5]
  | _, _ => []
  end.

