  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S0;S1] [S0;S0;S1] 1 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S1;S1])) 6 12.
Definition ch_farm1_0_1RB0LC_1LC1RD_0RD1LC_1RA0LC : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWinR 6);RB (SCycL 3 0);RB (SWin 3)].
