    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LC_1LC1RD_0RD1LC_1RA0LC | exact ok_iarm0_1_1RB0LC_1LC1RD_0RD1LC_1RA0LC]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LC_1LC1RD_0RD1LC_1RA0LC | exact ok_iarm1_0_1RB0LC_1LC1RD_0RD1LC_1RA0LC]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LC_1LC1RD_0RD1LC_1RA0LC | exact ok_iarm1_1_1RB0LC_1LC1RD_0RD1LC_1RA0LC]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LC_1LC1RD_0RD1LC_1RA0LC | exact ok_iarm2_0_1RB0LC_1LC1RD_0RD1LC_1RA0LC]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LC_1LC1RD_0RD1LC_1RA0LC | exact ok_iarm2_1_1RB0LC_1LC1RD_0RD1LC_1RA0LC]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

