  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S0] [S0;S1;S0] 1 0 [S1;S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S0;S1])) 8 10.
Definition ch_farm1_1_1RB0LD_1LC0RC_1RA1LD_0RA1LC : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 2);RB (SCycL 5 0);RB (SWin 5)].
