  match r, ph with
  | 1, 0 => farm1_0_1RB0LD_1LC1LB_1LD1RC_0RC1LA
  | _, _ => farm1_0_1RB0LD_1LC1LB_1LD1RC_0RC1LA  (* unreachable: 0 < r < N0 + st *)
  end.

