Lemma farm_rhs_1RB0LD_1LC1RC_1RA0LD_0RA1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB0LD_1LC1RC_1RA0LD_0RA1LD r ph)
                  (astride 1 1 r) (fm2_1RB0LD_1LC1RC_1RA0LD_0RA1LD r ph)
                  (f_to (fam_fill FAM ph))
                  (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph)))
    = cpad (padl_1RB0LD_1LC1RC_1RA0LD_0RA1LD r ph) (padr_1RB0LD_1LC1RC_1RA0LD_0RA1LD r ph) (lr_rhs (farm_1RB0LD_1LC1RC_1RA0LD_0RA1LD r ph)).
Proof.
