  match d, r with
  | 0, 0 => iarm0_0_1RB0LD_1LC1RC_1RA0LD_0RC1LD
  | 0, 1 => iarm0_1_1RB0LD_1LC1RC_1RA0LD_0RC1LD
  | 1, 0 => iarm1_0_1RB0LD_1LC1RC_1RA0LD_0RC1LD
