  | 2, 0 => iarm2_0_1RB0LD_1LC1RC_1RA0LD_0RC1LD
  | 2, 1 => iarm2_1_1RB0LD_1LC1RC_1RA0LD_0RC1LD
  | _, _ => iarm0_0_1RB0LD_1LC1RC_1RA0LD_0RC1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

