  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S1] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0;S1] [] 0 0 [])) 0 4.
Definition ch_iarm1_0_1RB0LD_1RC0LA_1LA1RA_0RA1LD : list rstep := [RB (SWin 4)].
